const record = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value)
function matches(actual: unknown, expected: unknown, path: string): void {
  if (Array.isArray(expected)) {
    if (!Array.isArray(actual) || actual.length !== expected.length) throw new Error('Stale bench GI ' + path)
    expected.forEach((value, i) => matches(actual[i], value, path + '[' + i + ']'))
  } else if (record(expected)) {
    if (!record(actual)) throw new Error('Stale bench GI ' + path)
    for (const [key, value] of Object.entries(expected)) matches(actual[key], value, path + '.' + key)
  } else if (actual !== expected) {
    throw new Error('Stale bench GI ' + path + ': expected ' + String(expected) + ', got ' + String(actual))
  }
}

